body {
  font-family: Arial, Helvetica, sans-serif;
  color: #222222;
  background-color: #FFFFFF;
  margin: 0;
}
.top-bar {
  background-color: #F1F1F1;
  font-size: 11px;
  padding: 4px 12px;
}
.mega-menu {
  background-color: #00205B;
}
.mega-menu > li > a {
  color: #FFFFFF;
  font-size: 13px;
  padding: 8px 14px;
  text-transform: uppercase;
}
.agenda-strip {
  background-color: #FDDA24;
  color: #00205B;
  font-weight: 700;
  padding: 6px 16px;
}
.news-tile {
  border: 1px solid #F1F1F1;
  padding: 10px;
}
a {
  color: #00205B;
  text-decoration: underline;
}
.pdf-icon {
  width: 14px;
  height: 14px;
  vertical-align: middle;
}

